{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table redtape_db.maplemonk.redtape_db_Mazhar_FactItems as SELECT c.* ,d.sale_quantity ,d.sales_value ,d.selling_price ,d.city ,d.Tax ,e.return_quantity ,e.return_sales FROM ( SELECT order_date, category_mapped, division, gender, REPLACE(SKU,\'`\',\'\') sku, REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\') article, SUM(\"Available Quantity\") closing_inventory FROM ( SELECT s.* ,pgd.division ,pgd.gender ,COALESCE(pma.category,pmf.category,pmac.category) category_mapped FROM (SELECT m.*,a.order_date FROM ( SELECT order_date::date AS order_date, sku, order_id FROM redtape_db.maplemonk.redtape_db_sales_consolidated QUALIFY ROW_NUMBER() OVER ( PARTITION BY order_date::date, sku, order_id ORDER BY order_date DESC ) = 1 ) a LEFT JOIN ( SELECT \"Report Generated Date\"::date AS report_date, REPLACE(\"SKU\",\'`\',\'\') AS sku, \"Available Quantity\" FROM redtape_db.maplemonk.easyecom_redtape_inventory_snapshot WHERE \"Report Generated Date\" IS NOT NULL ) m ON a.order_date = m.report_date AND a.sku = m.sku ) s LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_gender_division ) WHERE rw = 1 ) pgd ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pgd.code LEFT JOIN ( SELECT * FROM ( SELECT code, \"FOR SELL THRU\" category, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_apparel ) WHERE rw = 1 ) pma ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pma.code LEFT JOIN ( SELECT * FROM ( SELECT code, gategory category, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_footwear ) WHERE rw = 1 ) pmf ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pmf.code LEFT JOIN ( SELECT * FROM ( SELECT code, category, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_accessories ) WHERE rw = 1 ) pmac ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pmac.code ) GROUP BY 1,2,3,4,5,6 ) c LEFT JOIN ( SELECT category_mapped, division, gender, sku, city, order_date::DATE AS order_date, SUM(quantity) sale_quantity, SUM(gross_sales_before_tax) sales_value, SUM(selling_price) selling_price, SUM(tax) tax FROM redtape_db.maplemonk.redtape_db_sales_consolidated GROUP BY 1,2,3,4,5,6 ) d ON c.gender = d.gender AND c.division = d.division AND c.category_mapped = d.category_mapped AND c.order_date = d.order_date AND c.sku = d.sku LEFT JOIN ( SELECT category_mapped, division, gender, sku, return_date::DATE AS return_date, SUM(total_returned_quantity) return_quantity, SUM(total_return_amount) return_sales FROM redtape_db.maplemonk.redtape_db_returns_consolidated GROUP BY 1,2,3,4,5 ) e ON c.gender = e.gender AND c.division = e.division AND c.category_mapped = e.category_mapped AND c.order_date = e.return_date AND c.sku = e.sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            